def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != background), key=lambda v: counts[v])

    # Join nearby, collinear marker points with color 2.
    max_gap = 7
    for r in range(h):
        pts = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(pts, pts[1:]):
            if b - a <= max_gap:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        pts = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(pts, pts[1:]):
            if b - a <= max_gap:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # When the points outline a rectangle, complete its four boundary strokes;
    # this also closes a short missing segment at a corner.
    dense_rows = [r for r in range(h) if sum(v == marker for v in grid[r]) >= 3]
    dense_cols = [c for c in range(w) if sum(grid[r][c] == marker for r in range(h)) >= 3]
    if len(dense_rows) >= 2 and len(dense_cols) >= 2:
        top, bottom = min(dense_rows), max(dense_rows)
        left, right = min(dense_cols), max(dense_cols)
        # Only treat the extrema as a rectangle if each corner has an anchor
        # or an adjacent edge contains a marker close to that corner.
        for r in (top, bottom):
            edge_pts = [c for c in range(w) if grid[r][c] == marker]
            if edge_pts and min(edge_pts) - left <= max_gap and right - max(edge_pts) <= max_gap:
                for c in range(left, right + 1):
                    if grid[r][c] == background:
                        out[r][c] = 2
        for c in (left, right):
            edge_pts = [r for r in range(h) if grid[r][c] == marker]
